def rotate_elements(nums: List[int], k: int) -> List[int]:
    vals = [x for x in nums if x >= 0]
    if not vals:
        return nums[:]
    r = k % len(vals)
    rotated = vals[r:] + vals[:r]          # cyclic left rotation by k
    result, j = [], 0
    for x in nums:
        if x >= 0:
            result.append(rotated[j])      # refill the non negative slots in order
            j += 1
        else:
            result.append(x)               # negatives stay put
    return result

