def preimage_size_fzf(k: int) -> int:
    def zeros(x):
        count = 0
        while x:
            x //= 5
            count += x                 # factors of 5 contributed at this power
        return count

    lo, hi = 0, 5 * k + 5             # smallest x with zeros(x) >= k lies in here
    while lo < hi:
