def ways_to_build_rooms(prevRoom: List[int]) -> int:
    MOD = 10 ** 9 + 7
    n = len(prevRoom)
    children = [[] for _ in range(n)]
    for room in range(1, n):
        children[prevRoom[room]].append(room)
    order = [0]
    for room in order:                     # BFS order: parents before children
        order.extend(children[room])
    size = [1] * n
    for room in reversed(order):
        if room:
            size[prevRoom[room]] += size[room]
    numerator = 1
    for i in range(2, n + 1):
        numerator = numerator * i % MOD    # n!
    denominator = 1
    for s in size:
        denominator = denominator * s % MOD
    return numerator * pow(denominator, MOD - 2, MOD) % MOD

def min_array_length(nums: list[int], k: int) -> int:
    if 0 in nums:
        return 1             # a zero absorbs every neighbour, so everything collapses
    blocks = 1
    product = nums[0]
    for x in nums[1:]:
        if product * x <= k:
            product *= x         # keep extending the current block
        else:
            blocks += 1          # start a new block at x
            product = x
    return blocks

def find_smallest_region(regions: list[list[str]], region1: str, region2: str) -> str:
    parent = {}
    for group in regions:
        outer = group[0]
        for inner in group[1:]:
            parent[inner] = outer

    # Every region on the path from region1 to the root, region1 included.
    on_path = set()
    cur = region1
    while cur is not None:
        on_path.add(cur)
        cur = parent.get(cur)

    # Climb from region2 until we hit that path.
    cur = region2
    while cur not in on_path:
        cur = parent[cur]
    return cur

def str2tree(s: str) -> Optional[TreeNode]:
    if not s:
        return None
    root = None
    stack = []           # nodes whose parenthesised children are still being read
    i, n = 0, len(s)
    while i < n:
        ch = s[i]
        if ch == ')':
            stack.pop()
            i += 1
        elif ch == '(':
            i += 1
        else:
            # parse an integer with an optional leading minus sign
            j = i + 1 if ch == '-' else i
            while j < n and s[j].isdigit():
                j += 1
            node = TreeNode(int(s[i:j]))
            i = j
            if stack:
                parent = stack[-1]
                if parent.left is None:
                    parent.left = node
                else:
                    parent.right = node
            else:
                root = node
            stack.append(node)
    return root

