def cut_off_tree(forest: list[list[int]]) -> int:
    m, n = len(forest), len(forest[0])
    trees = sorted((forest[r][c], r, c) for r in range(m) for c in range(n) if forest[r][c] > 1)

    def bfs(sr, sc, tr, tc):
        # shortest path treating only 0 cells as walls
        if (sr, sc) == (tr, tc):
            return 0
        seen = [[False] * n for _ in range(m)]
        seen[sr][sc] = True
        frontier = [(sr, sc)]
        dist = 0
        while frontier:
            dist += 1
            nxt = []
            for r, c in frontier:
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if 0 <= nr < m and 0 <= nc < n and not seen[nr][nc] and forest[nr][nc] != 0:
                        if (nr, nc) == (tr, tc):
                            return dist
                        seen[nr][nc] = True
                        nxt.append((nr, nc))
            frontier = nxt
        return -1

    total = 0
    r, c = 0, 0
    for _, tr, tc in trees:
        d = bfs(r, c, tr, tc)
        if d < 0:
            return -1
        total += d
        r, c = tr, tc
    return total

