def find_critical_and_pseudo_critical_edges(n: int, edges: list[list[int]]) -> list[list[int]]:
    order = sorted(range(len(edges)), key=lambda i: edges[i][2])

    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def kruskal(skip, force):
        """MST weight using the edges in weight order; skip one edge, force another in first."""
        parent = list(range(n))
        weight, used = 0, 0
        if force >= 0:
            a, b, w = edges[force]
            parent[find(parent, a)] = find(parent, b)
            weight += w; used += 1
        for i in order:
            if i == skip or i == force:
                continue
            a, b, w = edges[i]
            ra, rb = find(parent, a), find(parent, b)
            if ra != rb:
                parent[ra] = rb
                weight += w; used += 1
                if used == n - 1:
                    break
        return weight if used == n - 1 else float("inf")

    best = kruskal(-1, -1)
    critical, pseudo = [], []
    for i in range(len(edges)):
        if kruskal(i, -1) > best:
            critical.append(i)
        elif kruskal(-1, i) == best:
            pseudo.append(i)
    return [critical, pseudo]

class FrontMiddleBackQueue:
    def __init__(self):
        self.left = deque()    # first half
        self.right = deque()   # second half, same length as left or one longer

    def _balance(self):
        if len(self.left) > len(self.right):
            self.right.appendleft(self.left.pop())
        elif len(self.right) > len(self.left) + 1:
            self.left.append(self.right.popleft())

    def pushFront(self, val: int) -> None:
        self.left.appendleft(val)
        self._balance()

    def pushMiddle(self, val: int) -> None:
        # the new element must become the front of the two middles
        if len(self.left) < len(self.right):
            self.left.append(val)
        else:
            self.right.appendleft(val)
        self._balance()

    def pushBack(self, val: int) -> None:
        self.right.append(val)
        self._balance()

    def popFront(self) -> int:
        if not self.right:
            return -1
        val = self.left.popleft() if self.left else self.right.popleft()
        self._balance()
        return val

    def popMiddle(self) -> int:
        if not self.right:
            return -1
        # equal lengths: the front middle is the last of left; otherwise it is right[0]
        val = self.left.pop() if len(self.left) == len(self.right) else self.right.popleft()
        self._balance()
        return val

    def popBack(self) -> int:
        if not self.right:
            return -1
        val = self.right.pop()
        self._balance()
        return val

