def max_score(points: list[int], m: int) -> int:
    n = len(points)

    def feasible(target: int) -> bool:
        moves = 0
        carry = 0                       # landings the current index already has
        for i, p in enumerate(points):
            need = (target + p - 1) // p - carry
            if i == n - 1 and need <= 0:
                break                   # last index already satisfied, no need to go there
            need = max(need, 1)         # we must at least step onto it to pass through
            moves += 2 * need - 1       # one move to arrive, two for every extra landing
            if moves > m:
                return False
            carry = need - 1            # bounces also landed on the next index
        return True

    lo, hi = 0, max(points) * m      # hi is an upper bound on any score
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

