def min_moves(matrix: List[str]) -> int:
    m, n = len(matrix), len(matrix[0])
    if matrix[m - 1][n - 1] == "#":
        return -1
    portals = defaultdict(list)       # letter -> cells carrying it
    for r in range(m):
        for c, ch in enumerate(matrix[r]):
            if ch != "." and ch != "#":
                portals[ch].append((r, c))
    INF = float("inf")
    dist = [[INF] * n for _ in range(m)]
    dist[0][0] = 0
    dq = deque([(0, 0)])
    spent = set()
    while dq:
        r, c = dq.popleft()
        d = dist[r][c]
        if r == m - 1 and c == n - 1:
            return d
        ch = matrix[r][c]
        if ch in portals and ch not in spent:
            spent.add(ch)
            for pr, pc in portals[ch]:
                if dist[pr][pc] > d:
                    dist[pr][pc] = d
                    dq.appendleft((pr, pc))     # free jump: front of the deque
        for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] != "#" and dist[nr][nc] > d + 1:
                dist[nr][nc] = d + 1
                dq.append((nr, nc))             # one step: back of the deque
    return -1

