def min_number_of_semesters(n: int, relations: List[List[int]], k: int) -> int:
    prereq = [0] * n                 # prereq[c] = bitmask of courses c depends on
    for a, b in relations:
        prereq[b - 1] |= 1 << (a - 1)
    full = (1 << n) - 1
    INF = float("inf")
    dp = [INF] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] == INF:
            continue
        avail = 0
        for c in range(n):
            if not mask >> c & 1 and prereq[c] & mask == prereq[c]:
                avail |= 1 << c
        nxt = dp[mask] + 1
        if bin(avail).count("1") <= k:
            if nxt < dp[mask | avail]:
                dp[mask | avail] = nxt
            continue
        sub = avail
        while sub:
            if bin(sub).count("1") == k and nxt < dp[mask | sub]:
                dp[mask | sub] = nxt
            sub = (sub - 1) & avail
    return dp[full]

