    extra = x - y                      # additional reduction a targeted operation gives

    def feasible(t: int) -> bool:
        base = t * y                   # every element loses at least this much
        targeted = 0
        for v in nums:
            if v > base:
                targeted += (v - base + extra - 1) // extra
