    found = []
    queue = deque(range(10))
    while queue:
        x = queue.popleft()
        if x > high:
            continue
        if x >= low:
            found.append(x)
        if x == 0:
            continue                      # 0 does not start longer stepping numbers
        last = x % 10
        if last > 0:
            queue.append(x * 10 + last - 1)
        if last < 9:
            queue.append(x * 10 + last + 1)
    found.sort()
