    if not isinstance(got, list) or len(got) != calls + 1 or got[0] is not None:
        return False
    allowed = set(values)
    for v in got[1:]:
        if v not in allowed:
            return False
    expected_each = calls / len(allowed)
    if calls >= 300 and expected_each >= 30:
        # with enough picks per value, every value should be drawn roughly uniformly
        from collections import Counter
        counts = Counter(got[1:])
        for v in allowed:
            if not 0.5 * expected_each <= counts.get(v, 0) <= 1.5 * expected_each:
                return False
    return True

