        self.count = [0] * 5

    def deposit(self, banknotes_count: List[int]) -> None:
        for i, c in enumerate(banknotes_count):
            self.count[i] += c

    def withdraw(self, amount: int) -> List[int]:
        taken = [0] * 5
        remaining = amount
        for i in range(4, -1, -1):                       # largest notes first
            use = min(self.count[i], remaining // self.VALUES[i])
            taken[i] = use
            remaining -= use * self.VALUES[i]
        if remaining != 0:
            return [-1]
        for i in range(5):
            self.count[i] -= taken[i]
        return taken

