def maximum_length(s: str) -> int:
    top = defaultdict(lambda: [0, 0, 0])    # letter -> three longest run lengths, descending
    for ch, group in itertools.groupby(s):
        length = sum(1 for _ in group)
        best = top[ch]
        if length > best[0]:
            best[0], best[1], best[2] = length, best[0], best[1]
        elif length > best[1]:
            best[1], best[2] = length, best[1]
        elif length > best[2]:
            best[2] = length
    answer = -1
    for a, b, c in top.values():
        candidate = max(a - 2, b if a > b else a - 1, c)
        if candidate > answer:
            answer = candidate
    return answer if answer > 0 else -1

