def restore_matrix(row_sum: List[int], col_sum: List[int]) -> List[List[int]]:
    n, m = len(row_sum), len(col_sum)
    rows = list(row_sum)          # amounts still to place in each row
    cols = list(col_sum)          # amounts still to place in each column
    matrix = [[0] * m for _ in range(n)]
    for i in range(n):
        row = matrix[i]
        for j in range(m):
            v = rows[i] if rows[i] < cols[j] else cols[j]
            if v:
                row[j] = v
                rows[i] -= v
                cols[j] -= v
            if rows[i] == 0:
                break               # the rest of this row stays zero
    return matrix

def min_length(s: str, num_ops: int) -> int:
    n = len(s)

    def flips_needed(limit: int) -> int:
        if limit == 1:
            mismatch = sum(1 for i, ch in enumerate(s) if ch != "01"[i % 2])
            return min(mismatch, n - mismatch)
        total = 0
        for _, run in itertools.groupby(s):
            total += sum(1 for _ in run) // (limit + 1)
        return total

    lo, hi = 1, n
    while lo < hi:
        mid = (lo + hi) // 2
        if flips_needed(mid) <= num_ops:
            hi = mid
        else:
            lo = mid + 1
    return lo

def maximum_product(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    heap = list(nums)
    heapq.heapify(heap)
    for _ in range(k):
        heapq.heapreplace(heap, heap[0] + 1)      # raise the current minimum
    product = 1
    for v in heap:
        product = product * v % MOD
    return product

