def count_combinations(pieces: List[str], positions: List[List[int]]) -> int:
    DIRS = {
        "rook": [(1, 0), (-1, 0), (0, 1), (0, -1)],
        "bishop": [(1, 1), (1, -1), (-1, 1), (-1, -1)],
    }
    DIRS["queen"] = DIRS["rook"] + DIRS["bishop"]
    n = len(pieces)

    # timelines[p] = list of moves; each move is the square occupied at seconds 0..7
    timelines = []
    for piece, (r, c) in zip(pieces, positions):
        moves = [[(r, c)] * 8]  # staying put
        for dr, dc in DIRS[piece]:
            for steps in range(1, 8):
                rr, cc = r + dr * steps, c + dc * steps
                if not (1 <= rr <= 8 and 1 <= cc <= 8):
                    break
                moves.append([(r + dr * min(t, steps), c + dc * min(t, steps)) for t in range(8)])
        timelines.append(moves)

    # compat[a][b][i] = bitmask of moves of piece b that never collide with move i of piece a
    compat = [[None] * n for _ in range(n)]
    for a in range(n):
        for b in range(a + 1, n):
            full_b = (1 << len(timelines[b])) - 1
            at = defaultdict(int)  # (second, square) -> mask of b moves there
            for j, path in enumerate(timelines[b]):
                for t, sq in enumerate(path):
                    at[(t, sq)] |= 1 << j
            masks = []
            for path in timelines[a]:
                bad = 0
                for t, sq in enumerate(path):
                    bad |= at.get((t, sq), 0)
                masks.append(full_b & ~bad)
            compat[a][b] = masks

    def count(k, allowed):
        if k == n - 1:
            return bin(allowed[k]).count("1")
        total = 0
        m = allowed[k]
        while m:
            low = m & -m
            i = low.bit_length() - 1
            m ^= low
            nxt = allowed[:]
            alive = True
            for j in range(k + 1, n):
                nxt[j] &= compat[k][j][i]
                if nxt[j] == 0:
                    alive = False
                    break
            if alive:
                total += count(k + 1, nxt)
        return total

    return count(0, [(1 << len(mv)) - 1 for mv in timelines])
